  1→/**
  2→ * OpenTelemetry SDK bootstrap for the Brain server.
  3→ *
  4→ * Pure function that reads env and returns a TelemetryHandle with
  5→ * TracerProvider, MeterProvider, LoggerProvider, and a shutdown function.
  6→ *
  7→ * Exporter selection:
  8→ * - Console exporters when OTEL_EXPORTER_OTLP_ENDPOINT is unset (dev)
  9→ * - OTLP HTTP exporters when OTEL_EXPORTER_OTLP_ENDPOINT is set (prod)
 10→ *
 11→ * Graceful degradation: if initialization fails, returns a no-op handle
 12→ * so the server can still start.
 13→ */
 14→
 15→import * as otelApi from "@opentelemetry/api";
 16→import type { TracerProvider as ApiTracerProvider, MeterProvider as ApiMeterProvider } from "@opentelemetry/api";
 17→import * as otelLogs from "@opentelemetry/api-logs";
 18→import type { LoggerProvider as ApiLoggerProvider } from "@opentelemetry/api-logs";
 19→
 20→// Destructure after namespace import for Bun CJS/ESM interop resilience
 21→const { trace, metrics, context } = otelApi;
 22→const { logs } = otelLogs;
 23→import { resourceFromAttributes } from "@opentelemetry/resources";
 24→import type { Resource } from "@opentelemetry/resources";
 25→import { ATTR_SERVICE_NAME, ATTR_SERVICE_VERSION } from "@opentelemetry/semantic-conventions";
 26→import { BasicTracerProvider, BatchSpanProcessor, ConsoleSpanExporter, SimpleSpanProcessor } from "@opentelemetry/sdk-trace-base";
 27→import { MeterProvider, PeriodicExportingMetricReader, ConsoleMetricExporter } from "@opentelemetry/sdk-metrics";
 28→import { LoggerProvider, SimpleLogRecordProcessor, ConsoleLogRecordExporter } from "@opentelemetry/sdk-logs";
 29→import { AsyncLocalStorageContextManager } from "@opentelemetry/context-async-hooks";
 30→
 31→export type ExporterType = "console" | "otlp" | "noop";
 32→
 33→export interface TelemetryHandle {
 34→  readonly tracerProvider: ApiTracerProvider;
 35→  readonly meterProvider: ApiMeterProvider;
 36→  readonly loggerProvider: ApiLoggerProvider;
 37→  readonly exporterType: ExporterType;
 38→  readonly shutdown: () => Promise<void>;
 39→}
 40→
 41→function buildResource(): Resource {
 42→  const serviceVersion = process.env.SERVICE_VERSION ?? "unknown";
 43→  return resourceFromAttributes({
 44→    [ATTR_SERVICE_NAME]: "osabio-server",
 45→    [ATTR_SERVICE_VERSION]: serviceVersion,
 46→  });
 47→}
 48→
 49→function createConsoleProviders(resource: Resource): {
 50→  tracerProvider: BasicTracerProvider;
 51→  meterProvider: MeterProvider;
 52→  loggerProvider: LoggerProvider;
 53→} {
 54→  const tracerProvider = new BasicTracerProvider({
 55→    resource,
 56→    spanProcessors: [new SimpleSpanProcessor(new ConsoleSpanExporter())],
 57→  });
 58→
 59→  const meterProvider = new MeterProvider({
 60→    resource,
 61→    readers: [new PeriodicExportingMetricReader({ exporter: new ConsoleMetricExporter() })],
 62→  });
 63→
 64→  const loggerProvider = new LoggerProvider({
 65→    resource,
 66→    processors: [new SimpleLogRecordProcessor(new ConsoleLogRecordExporter())],
 67→  });
 68→
 69→  return { tracerProvider, meterProvider, loggerProvider };
 70→}
 71→
 72→function createOtlpProviders(resource: Resource, endpoint: string): {
 73→  tracerProvider: BasicTracerProvider;
 74→  meterProvider: MeterProvider;
 75→  loggerProvider: LoggerProvider;
 76→} {
 77→  // Bun supports synchronous require() for these packages
 78→  const { OTLPTraceExporter } = require("@opentelemetry/exporter-trace-otlp-http");
 79→  const { OTLPMetricExporter } = require("@opentelemetry/exporter-metrics-otlp-http");
 80→  const { OTLPLogExporter } = require("@opentelemetry/exporter-logs-otlp-http");
 81→
 82→  const tracerProvider = new BasicTracerProvider({
 83→    resource,
 84→    spanProcessors: [new BatchSpanProcessor(new OTLPTraceExporter({ url: `${endpoint}/v1/traces` }))],
 85→  });
 86→
 87→  const meterProvider = new MeterProvider({
 88→    resource,
 89→    readers: [
 90→      new PeriodicExportingMetricReader({
 91→        exporter: new OTLPMetricExporter({ url: `${endpoint}/v1/metrics` }),
 92→      }),
 93→    ],
 94→  });
 95→
 96→  const loggerProvider = new LoggerProvider({
 97→    resource,
 98→    processors: [new SimpleLogRecordProcessor(new OTLPLogExporter({ url: `${endpoint}/v1/logs` }))],
 99→  });
100→
101→  return { tracerProvider, meterProvider, loggerProvider };
102→}
