104→function buildShutdown(
105→  tracerProvider: BasicTracerProvider,
106→  meterProvider: MeterProvider,
107→  loggerProvider: LoggerProvider,
108→): () => Promise<void> {
109→  let alreadyShutDown = false;
110→
111→  return async () => {
112→    if (alreadyShutDown) return;
113→    alreadyShutDown = true;
114→
115→    await Promise.allSettled([
116→      tracerProvider.forceFlush().then(() => tracerProvider.shutdown()),
117→      meterProvider.forceFlush().then(() => meterProvider.shutdown()),
118→      loggerProvider.forceFlush().then(() => loggerProvider.shutdown()),
119→    ]);
120→  };
121→}
122→
123→function registerProviders(
124→  tracerProvider: BasicTracerProvider,
125→  meterProvider: MeterProvider,
126→  loggerProvider: LoggerProvider,
127→): void {
128→  const contextManager = new AsyncLocalStorageContextManager();
129→  contextManager.enable();
130→  context.setGlobalContextManager(contextManager);
131→
132→  trace.setGlobalTracerProvider(tracerProvider);
133→  metrics.setGlobalMeterProvider(meterProvider);
134→  logs.setGlobalLoggerProvider(loggerProvider);
135→}
136→
137→export function createNoopTelemetryHandle(): TelemetryHandle {
138→  return {
139→    tracerProvider: trace.getTracerProvider(),
140→    meterProvider: metrics.getMeterProvider(),
141→    loggerProvider: logs.getLoggerProvider(),
142→    exporterType: "noop",
143→    shutdown: async () => {},
144→  };
145→}
