147→/**
148→ * Initialize OpenTelemetry SDK.
149→ *
150→ * Reads OTEL_EXPORTER_OTLP_ENDPOINT from env to select exporter type.
151→ * Returns a TelemetryHandle with providers and a shutdown function.
152→ * Falls back to no-op handle on failure so the server can still start.
153→ */
154→export function initTelemetry(): TelemetryHandle {
155→  try {
156→    const resource = buildResource();
157→    const endpoint = process.env.OTEL_EXPORTER_OTLP_ENDPOINT;
158→
159→    const { tracerProvider, meterProvider, loggerProvider } = endpoint
160→      ? createOtlpProviders(resource, endpoint)
161→      : createConsoleProviders(resource);
162→
163→    registerProviders(tracerProvider, meterProvider, loggerProvider);
164→
165→    return {
